import { randomUUID } from 'node:crypto';

import { HttpError } from '../../lib/errors/http-error.js';

const clone = (value) => structuredClone(value);
const nowIso = () => new Date().toISOString();
function parseJson(value, fallback) { if (value == null) return fallback; if (typeof value === 'object') return value; try { return JSON.parse(value); } catch { return fallback; } }
function conflict(record, expectedVersion) { throw new HttpError(409, 'Identity record changed since it was loaded.', { details: { actualVersion: record.version, code: 'identity_version_conflict', expectedVersion } }); }

export function createInMemoryIdentityRepository() {
  const state = {
    accessReviewCampaignRuns: new Map(), accessReviewCampaigns: new Map(), accessReviewItems: new Map(), accessReviews: new Map(), credentials: new Map(), domains: new Map(),
    breakGlassPolicies: new Map(), groupMemberships: new Map(), groups: new Map(), impersonationGrants: new Map(), oidcTransactions: new Map(), policies: new Map(), roles: new Map(), samlTransactions: new Map(), serviceAccounts: new Map(),
  };
  const list = (collection, tenantId) => clone([...collection.values()].filter((record) => record.tenantId === tenantId));
  function create(collection, input, tenantId, extra = {}) { const now = nowIso(); const record = { ...clone(input), ...extra, createdAt: now, id: randomUUID(), tenantId, updatedAt: now, version: 1 }; collection.set(record.id, record); return clone(record); }
  function update(collection, id, input, tenantId) { const record = collection.get(id); if (!record || record.tenantId !== tenantId) return null; if (record.version !== input.expectedVersion) conflict(record, input.expectedVersion); const { expectedVersion: _expectedVersion, ...changes } = input; Object.assign(record, clone(changes), { updatedAt: nowIso(), version: record.version + 1 }); return clone(record); }
  function remove(collection, id, expectedVersion, tenantId) { const record = collection.get(id); if (!record || record.tenantId !== tenantId) return false; if (record.version !== expectedVersion) conflict(record, expectedVersion); collection.delete(id); return true; }
  return {
    state,
    async getPolicy({ tenantId }) { return clone(state.policies.get(tenantId) ?? null); },
    async getImpersonationGrant({ grantId, tenantId }) { const record = state.impersonationGrants.get(grantId); return clone(record?.tenantId === tenantId ? record : null); },
    async getBreakGlassPolicy({ tenantId }) { return clone(state.breakGlassPolicies.get(tenantId) ?? null); },
    async upsertBreakGlassPolicy({ input, tenantId, updatedBy }) { const current = state.breakGlassPolicies.get(tenantId); if ((current?.version ?? 0) !== input.expectedVersion) conflict(current ?? { version: 0 }, input.expectedVersion); const now = nowIso(); const { expectedVersion: _expectedVersion, ...value } = input; const record = { ...clone(value), createdAt: current?.createdAt ?? now, tenantId, updatedAt: now, updatedBy, version: (current?.version ?? 0) + 1 }; state.breakGlassPolicies.set(tenantId, record); return clone(record); },
    async findVerifiedDomain({ domain }) { const record = [...state.domains.values()].find((item) => item.domain === domain.toLowerCase() && item.status === 'verified'); return clone(record ?? null); },
    async resolveUserCapabilities({ tenantId, userId }) { const groupIds = new Set([...state.groupMemberships.values()].filter((item) => item.tenantId === tenantId && item.userId === userId).map((item) => item.groupId)); const roleKeys = new Set([...state.groups.values()].filter((group) => group.tenantId === tenantId && groupIds.has(group.id)).flatMap((group) => group.roleKeys)); return [...new Set([...state.roles.values()].filter((role) => role.tenantId === tenantId && roleKeys.has(role.key)).flatMap((role) => role.capabilities))].sort(); },
    async upsertPolicy({ input, tenantId, updatedBy }) { const current = state.policies.get(tenantId); if (current && current.version !== input.expectedVersion) conflict(current, input.expectedVersion); if (!current && input.expectedVersion !== 0) conflict({ version: 0 }, input.expectedVersion); const now = nowIso(); const { expectedVersion: _expectedVersion, ...value } = input; const record = { ...clone(value), createdAt: current?.createdAt ?? now, tenantId, updatedAt: now, updatedBy, version: (current?.version ?? 0) + 1 }; state.policies.set(tenantId, record); return clone(record); },
    createDomain: ({ input, tenantId, tokenHash }) => create(state.domains, { ...input, status: 'pending', tokenHash, verifiedAt: null }, tenantId),
    updateDomain: ({ domainId, input, tenantId }) => update(state.domains, domainId, input, tenantId),
    deleteDomain: ({ domainId, expectedVersion, tenantId }) => remove(state.domains, domainId, expectedVersion, tenantId),
    createRole: ({ input, tenantId }) => create(state.roles, input, tenantId),
    updateRole: ({ input, roleId, tenantId }) => update(state.roles, roleId, input, tenantId),
    deleteRole: ({ expectedVersion, roleId, tenantId }) => { if ([...state.groups.values()].some((group) => group.tenantId === tenantId && group.roleKeys.includes(state.roles.get(roleId)?.key))) throw new HttpError(409, 'Remove this role from groups before deleting it.'); return remove(state.roles, roleId, expectedVersion, tenantId); },
    createGroup: ({ input, tenantId }) => create(state.groups, input, tenantId),
    updateGroup: ({ groupId, input, tenantId }) => update(state.groups, groupId, input, tenantId),
    deleteGroup: ({ expectedVersion, groupId, tenantId }) => { const removed = remove(state.groups, groupId, expectedVersion, tenantId); if (removed) for (const [key, membership] of state.groupMemberships) if (membership.tenantId === tenantId && membership.groupId === groupId) state.groupMemberships.delete(key); return removed; },
    async addGroupMember({ groupId, tenantId, userId }) { const key = `${tenantId}:${groupId}:${userId}`; if (!state.groupMemberships.has(key)) state.groupMemberships.set(key, { createdAt: nowIso(), groupId, tenantId, userId }); return clone(state.groupMemberships.get(key)); },
    async removeGroupMember({ groupId, tenantId, userId }) { return state.groupMemberships.delete(`${tenantId}:${groupId}:${userId}`); },
    createAccessReview: ({ input, items, tenantId, userId }) => { const review = create(state.accessReviews, { ...input, completedAt: null, createdBy: userId, status: 'open' }, tenantId); for (const item of items) create(state.accessReviewItems, { ...item, decision: 'pending', decidedAt: null, decidedBy: null, note: '', reviewId: review.id }, tenantId); return review; },
    createAccessReviewCampaign: ({ input, tenantId, userId }) => create(state.accessReviewCampaigns, { ...input, createdBy: userId, lastRunAt: null, runCount: 0 }, tenantId),
    updateAccessReviewCampaign: ({ campaignId, input, tenantId }) => update(state.accessReviewCampaigns, campaignId, input, tenantId),
    async listDueAccessReviewCampaigns({ limit = 100, now = new Date() } = {}) { return clone([...state.accessReviewCampaigns.values()].filter((item) => item.enabled && Date.parse(item.nextRunAt) <= now.getTime()).sort((left, right) => left.nextRunAt.localeCompare(right.nextRunAt)).slice(0, limit)); },
    async materializeAccessReviewCampaign({ campaignId, items, nextRunAt, reviewInput, scheduledFor, tenantId }) { const campaign = state.accessReviewCampaigns.get(campaignId); if (!campaign || campaign.tenantId !== tenantId || !campaign.enabled || campaign.nextRunAt !== scheduledFor) return { created: false, review: null, run: null }; const existing = [...state.accessReviewCampaignRuns.values()].find((item) => item.tenantId === tenantId && item.campaignId === campaignId && item.scheduledFor === scheduledFor); if (existing) return { created: false, review: clone(state.accessReviews.get(existing.reviewId) ?? null), run: clone(existing) }; const empty = items.length === 0; const review = create(state.accessReviews, { ...reviewInput, completedAt: empty ? nowIso() : null, createdBy: campaign.createdBy, status: empty ? 'completed' : 'open' }, tenantId); for (const item of items) create(state.accessReviewItems, { ...item, decision: 'pending', decidedAt: null, decidedBy: null, note: '', reviewId: review.id }, tenantId); const run = create(state.accessReviewCampaignRuns, { campaignId, reviewId: review.id, scheduledFor }, tenantId); Object.assign(campaign, { lastRunAt: nowIso(), nextRunAt, runCount: campaign.runCount + 1, updatedAt: nowIso(), version: campaign.version + 1 }); return { campaign: clone(campaign), created: true, review, run }; },
    updateAccessReviewItem: ({ input, itemId, tenantId, userId }) => update(state.accessReviewItems, itemId, { ...input, decidedAt: nowIso(), decidedBy: userId }, tenantId),
    async completeAccessReviewIfReady({ reviewId, tenantId }) { const review = state.accessReviews.get(reviewId); if (!review || review.tenantId !== tenantId) return null; const hasPending = [...state.accessReviewItems.values()].some((item) => item.tenantId === tenantId && item.reviewId === reviewId && item.decision === 'pending'); if (!hasPending && review.status === 'open') Object.assign(review, { completedAt: nowIso(), status: 'completed', updatedAt: nowIso(), version: review.version + 1 }); return clone(review); },
    createServiceAccount: ({ input, tenantId, userId }) => create(state.serviceAccounts, { ...input, createdBy: userId, enabled: true, lastUsedAt: null }, tenantId),
    updateServiceAccount: ({ accountId, input, tenantId }) => update(state.serviceAccounts, accountId, input, tenantId),
    createCredential: ({ accountId, expiresAt, prefix, secretHash, tenantId, userId }) => create(state.credentials, { accountId, createdBy: userId, expiresAt, lastUsedAt: null, prefix, revokedAt: null, secretHash }, tenantId),
    async authenticateCredential({ secretHash }) { const credential = [...state.credentials.values()].find((record) => record.secretHash === secretHash); if (!credential || credential.revokedAt || (credential.expiresAt && Date.parse(credential.expiresAt) <= Date.now())) return null; const account = state.serviceAccounts.get(credential.accountId); if (!account?.enabled || (account.expiresAt && Date.parse(account.expiresAt) <= Date.now())) return null; return clone({ account, credential }); },
    async markCredentialUsed({ credentialId, tenantId }) { const credential = state.credentials.get(credentialId); if (!credential || credential.tenantId !== tenantId) return false; credential.lastUsedAt = nowIso(); const account = state.serviceAccounts.get(credential.accountId); if (account) account.lastUsedAt = credential.lastUsedAt; return true; },
    async revokeCredentials({ accountId, tenantId }) { const revokedAt = nowIso(); for (const credential of state.credentials.values()) if (credential.tenantId === tenantId && credential.accountId === accountId && !credential.revokedAt) { credential.revokedAt = revokedAt; credential.updatedAt = revokedAt; credential.version += 1; } },
    createImpersonationGrant: ({ input, requesterUserId, tenantId }) => create(state.impersonationGrants, { ...input, approvedAt: null, approvedBy: null, decisionNote: '', endedAt: null, requesterUserId, status: 'pending' }, tenantId),
    updateImpersonationGrant: ({ grantId, input, tenantId }) => update(state.impersonationGrants, grantId, input, tenantId),
    async createOidcTransaction({ codeVerifier, expiresAt, nonce, redirectPath, stateHash, tenantId }) { const record = { codeVerifier, createdAt: nowIso(), expiresAt, nonce, redirectPath, stateHash, tenantId }; state.oidcTransactions.set(stateHash, record); return clone(record); },
    async consumeOidcTransaction({ stateHash }) { const record = state.oidcTransactions.get(stateHash); state.oidcTransactions.delete(stateHash); if (!record || Date.parse(record.expiresAt) <= Date.now()) return null; return clone(record); },
    async createSamlTransaction({ expiresAt, redirectPath, stateHash, tenantId }) { const record = { cacheValue: null, createdAt: nowIso(), expiresAt, redirectPath, requestConsumedAt: null, requestId: null, stateConsumedAt: null, stateHash, tenantId }; state.samlTransactions.set(stateHash, record); return clone(record); },
    async attachSamlRequest({ cacheValue, requestId, stateHash }) { const record = state.samlTransactions.get(stateHash); if (!record || record.requestId || Date.parse(record.expiresAt) <= Date.now()) return null; Object.assign(record, { cacheValue, requestId }); return clone(record); },
    async consumeSamlState({ stateHash }) { const record = state.samlTransactions.get(stateHash); if (!record || record.stateConsumedAt || Date.parse(record.expiresAt) <= Date.now()) return null; record.stateConsumedAt = nowIso(); return clone(record); },
    async getSamlRequest({ requestId }) { const record = [...state.samlTransactions.values()].find((item) => item.requestId === requestId && !item.requestConsumedAt && Date.parse(item.expiresAt) > Date.now()); return record?.cacheValue ?? null; },
    async consumeSamlRequest({ requestId }) { const record = [...state.samlTransactions.values()].find((item) => item.requestId === requestId && !item.requestConsumedAt && Date.parse(item.expiresAt) > Date.now()); if (!record) return null; record.requestConsumedAt = nowIso(); return record.cacheValue; },
    async listSnapshot({ tenantId }) { return { accessReviewCampaignRuns: list(state.accessReviewCampaignRuns, tenantId), accessReviewCampaigns: list(state.accessReviewCampaigns, tenantId), accessReviewItems: list(state.accessReviewItems, tenantId), accessReviews: list(state.accessReviews, tenantId), breakGlassPolicy: clone(state.breakGlassPolicies.get(tenantId) ?? null), credentials: list(state.credentials, tenantId), domains: list(state.domains, tenantId), groupMemberships: list(state.groupMemberships, tenantId), groups: list(state.groups, tenantId), impersonationGrants: list(state.impersonationGrants, tenantId), policy: clone(state.policies.get(tenantId) ?? null), roles: list(state.roles, tenantId), serviceAccounts: list(state.serviceAccounts, tenantId) }; },
  };
}

export async function ensureMysqlIdentitySchema(executor) {
  const statements = [
    `CREATE TABLE IF NOT EXISTS tenant_identity_policies (tenant_id VARCHAR(36) PRIMARY KEY, sso_mode VARCHAR(16) NOT NULL, login_enforcement VARCHAR(16) NOT NULL, jit_enabled BOOLEAN NOT NULL, default_role_key VARCHAR(64) NOT NULL, provider_json JSON NOT NULL, updated_by VARCHAR(128) NOT NULL, version INT NOT NULL DEFAULT 1, created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL)`,
    `CREATE TABLE IF NOT EXISTS tenant_verified_domains (id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL, domain VARCHAR(253) NOT NULL, verification_method VARCHAR(32) NOT NULL, verification_token_hash CHAR(64) NOT NULL, status VARCHAR(32) NOT NULL, verified_at DATETIME(3) NULL, version INT NOT NULL DEFAULT 1, created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, UNIQUE KEY uq_verified_domain (domain), KEY idx_verified_domains_tenant (tenant_id, status))`,
    `CREATE TABLE IF NOT EXISTS tenant_custom_roles (id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL, role_key VARCHAR(64) NOT NULL, name VARCHAR(120) NOT NULL, description TEXT NOT NULL, capabilities_json JSON NOT NULL, version INT NOT NULL DEFAULT 1, created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, UNIQUE KEY uq_custom_role (tenant_id, role_key))`,
    `CREATE TABLE IF NOT EXISTS identity_groups (id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL, name VARCHAR(160) NOT NULL, description TEXT NOT NULL, external_id VARCHAR(255) NOT NULL, role_keys_json JSON NOT NULL, version INT NOT NULL DEFAULT 1, created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, UNIQUE KEY uq_identity_group_name (tenant_id, name), KEY idx_identity_group_external (tenant_id, external_id))`,
    `CREATE TABLE IF NOT EXISTS identity_group_memberships (id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL, group_id VARCHAR(36) NOT NULL, user_id VARCHAR(128) NOT NULL, created_at DATETIME(3) NOT NULL, UNIQUE KEY uq_identity_group_member (tenant_id, group_id, user_id), KEY idx_identity_group_user (tenant_id, user_id))`,
    `CREATE TABLE IF NOT EXISTS access_reviews (id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL, name VARCHAR(240) NOT NULL, scope VARCHAR(32) NOT NULL, reviewer_user_id VARCHAR(128) NOT NULL, due_at DATETIME(3) NOT NULL, status VARCHAR(32) NOT NULL, created_by VARCHAR(128) NOT NULL, completed_at DATETIME(3) NULL, version INT NOT NULL DEFAULT 1, created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, KEY idx_access_reviews_due (tenant_id, status, due_at))`,
    `CREATE TABLE IF NOT EXISTS access_review_items (id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL, review_id VARCHAR(36) NOT NULL, subject_type VARCHAR(32) NOT NULL, subject_id VARCHAR(128) NOT NULL, access_json JSON NOT NULL, decision VARCHAR(32) NOT NULL, note TEXT NOT NULL, decided_by VARCHAR(128) NULL, decided_at DATETIME(3) NULL, version INT NOT NULL DEFAULT 1, created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, KEY idx_access_review_items (tenant_id, review_id, decision))`,
    `CREATE TABLE IF NOT EXISTS service_accounts (id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL, name VARCHAR(160) NOT NULL, description TEXT NOT NULL, scopes_json JSON NOT NULL, project_ids_json JSON NOT NULL, enabled BOOLEAN NOT NULL, expires_at DATETIME(3) NULL, last_used_at DATETIME(3) NULL, created_by VARCHAR(128) NOT NULL, version INT NOT NULL DEFAULT 1, created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, UNIQUE KEY uq_service_account_name (tenant_id, name), KEY idx_service_accounts_status (tenant_id, enabled, expires_at))`,
    `CREATE TABLE IF NOT EXISTS service_account_credentials (id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL, account_id VARCHAR(36) NOT NULL, credential_prefix VARCHAR(24) NOT NULL, secret_hash CHAR(64) NOT NULL, expires_at DATETIME(3) NULL, revoked_at DATETIME(3) NULL, last_used_at DATETIME(3) NULL, created_by VARCHAR(128) NOT NULL, version INT NOT NULL DEFAULT 1, created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, UNIQUE KEY uq_service_credential_hash (secret_hash), KEY idx_service_credentials_account (tenant_id, account_id, revoked_at))`,
    `CREATE TABLE IF NOT EXISTS impersonation_grants (id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL, requester_user_id VARCHAR(128) NOT NULL, target_user_id VARCHAR(128) NOT NULL, reason TEXT NOT NULL, status VARCHAR(32) NOT NULL, expires_at DATETIME(3) NOT NULL, approved_by VARCHAR(128) NULL, approved_at DATETIME(3) NULL, decision_note TEXT NOT NULL, ended_at DATETIME(3) NULL, version INT NOT NULL DEFAULT 1, created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, KEY idx_impersonation_status (tenant_id, status, expires_at))`,
    `CREATE TABLE IF NOT EXISTS identity_oidc_transactions (state_hash CHAR(64) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL, code_verifier VARCHAR(256) NOT NULL, nonce VARCHAR(256) NOT NULL, redirect_path VARCHAR(2000) NOT NULL, expires_at DATETIME(3) NOT NULL, created_at DATETIME(3) NOT NULL, KEY idx_oidc_transactions_expiry (expires_at), KEY idx_oidc_transactions_tenant (tenant_id, expires_at))`,
  ];
  for (const statement of statements) await executor.execute(statement);
}

export async function ensureMysqlBreakGlassSchema(executor) {
  await executor.execute(`CREATE TABLE IF NOT EXISTS tenant_break_glass_policies (tenant_id VARCHAR(36) PRIMARY KEY, enabled BOOLEAN NOT NULL, user_ids_json JSON NOT NULL, max_session_minutes INT NOT NULL, updated_by VARCHAR(128) NOT NULL, version INT NOT NULL DEFAULT 1, created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL)`);
}

export async function ensureMysqlAccessReviewCampaignSchema(executor) {
  await executor.execute(`CREATE TABLE IF NOT EXISTS access_review_campaigns (id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL, name VARCHAR(240) NOT NULL, scope VARCHAR(32) NOT NULL, reviewer_user_id VARCHAR(128) NOT NULL, interval_days INT NOT NULL, duration_days INT NOT NULL, next_run_at DATETIME(3) NOT NULL, enabled BOOLEAN NOT NULL, created_by VARCHAR(128) NOT NULL, last_run_at DATETIME(3) NULL, run_count INT NOT NULL DEFAULT 0, version INT NOT NULL DEFAULT 1, created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, KEY idx_access_review_campaigns_due (enabled, next_run_at), KEY idx_access_review_campaigns_tenant (tenant_id, enabled))`);
  await executor.execute(`CREATE TABLE IF NOT EXISTS access_review_campaign_runs (id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL, campaign_id VARCHAR(36) NOT NULL, review_id VARCHAR(36) NOT NULL, scheduled_for DATETIME(3) NOT NULL, version INT NOT NULL DEFAULT 1, created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, UNIQUE KEY uq_access_review_campaign_run (tenant_id, campaign_id, scheduled_for), KEY idx_access_review_campaign_runs_review (tenant_id, review_id))`);
}

export async function ensureMysqlSamlTransactionSchema(executor) {
  await executor.execute(`CREATE TABLE IF NOT EXISTS identity_saml_transactions (state_hash CHAR(64) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL, redirect_path VARCHAR(2000) NOT NULL, request_id VARCHAR(256) NULL, cache_value VARCHAR(2000) NULL, expires_at DATETIME(3) NOT NULL, state_consumed_at DATETIME(3) NULL, request_consumed_at DATETIME(3) NULL, created_at DATETIME(3) NOT NULL, UNIQUE KEY uq_saml_request_id (request_id), KEY idx_saml_transactions_expiry (expires_at), KEY idx_saml_transactions_tenant (tenant_id, expires_at))`);
}

const maps = {
  reviewCampaign: (row) => row && ({ createdAt: new Date(row.created_at).toISOString(), createdBy: row.created_by, durationDays: Number(row.duration_days), enabled: Boolean(row.enabled), id: row.id, intervalDays: Number(row.interval_days), lastRunAt: row.last_run_at ? new Date(row.last_run_at).toISOString() : null, name: row.name, nextRunAt: new Date(row.next_run_at).toISOString(), reviewerUserId: row.reviewer_user_id, runCount: Number(row.run_count), scope: row.scope, tenantId: row.tenant_id, updatedAt: new Date(row.updated_at).toISOString(), version: Number(row.version) }),
  reviewCampaignRun: (row) => row && ({ campaignId: row.campaign_id, createdAt: new Date(row.created_at).toISOString(), id: row.id, reviewId: row.review_id, scheduledFor: new Date(row.scheduled_for).toISOString(), tenantId: row.tenant_id, updatedAt: new Date(row.updated_at).toISOString(), version: Number(row.version) }),
  breakGlassPolicy: (row) => row && ({ createdAt: new Date(row.created_at).toISOString(), enabled: Boolean(row.enabled), maxSessionMinutes: Number(row.max_session_minutes), tenantId: row.tenant_id, updatedAt: new Date(row.updated_at).toISOString(), updatedBy: row.updated_by, userIds: parseJson(row.user_ids_json, []), version: Number(row.version) }),
  policy: (row) => row && ({ createdAt: new Date(row.created_at).toISOString(), defaultRoleKey: row.default_role_key, jitEnabled: Boolean(row.jit_enabled), loginEnforcement: row.login_enforcement, provider: parseJson(row.provider_json, {}), ssoMode: row.sso_mode, tenantId: row.tenant_id, updatedAt: new Date(row.updated_at).toISOString(), updatedBy: row.updated_by, version: Number(row.version) }),
  domain: (row) => row && ({ createdAt: new Date(row.created_at).toISOString(), domain: row.domain, id: row.id, status: row.status, tenantId: row.tenant_id, tokenHash: row.verification_token_hash, updatedAt: new Date(row.updated_at).toISOString(), verificationMethod: row.verification_method, verifiedAt: row.verified_at ? new Date(row.verified_at).toISOString() : null, version: Number(row.version) }),
  role: (row) => row && ({ capabilities: parseJson(row.capabilities_json, []), createdAt: new Date(row.created_at).toISOString(), description: row.description, id: row.id, key: row.role_key, name: row.name, tenantId: row.tenant_id, updatedAt: new Date(row.updated_at).toISOString(), version: Number(row.version) }),
  group: (row) => row && ({ createdAt: new Date(row.created_at).toISOString(), description: row.description, externalId: row.external_id, id: row.id, name: row.name, roleKeys: parseJson(row.role_keys_json, []), tenantId: row.tenant_id, updatedAt: new Date(row.updated_at).toISOString(), version: Number(row.version) }),
  groupMembership: (row) => row && ({ createdAt: new Date(row.created_at).toISOString(), groupId: row.group_id, id: row.id, tenantId: row.tenant_id, userId: row.user_id }),
  review: (row) => row && ({ completedAt: row.completed_at ? new Date(row.completed_at).toISOString() : null, createdAt: new Date(row.created_at).toISOString(), createdBy: row.created_by, dueAt: new Date(row.due_at).toISOString(), id: row.id, name: row.name, reviewerUserId: row.reviewer_user_id, scope: row.scope, status: row.status, tenantId: row.tenant_id, updatedAt: new Date(row.updated_at).toISOString(), version: Number(row.version) }),
  reviewItem: (row) => row && ({ access: parseJson(row.access_json, {}), createdAt: new Date(row.created_at).toISOString(), decidedAt: row.decided_at ? new Date(row.decided_at).toISOString() : null, decidedBy: row.decided_by, decision: row.decision, id: row.id, note: row.note, reviewId: row.review_id, subjectId: row.subject_id, subjectType: row.subject_type, tenantId: row.tenant_id, updatedAt: new Date(row.updated_at).toISOString(), version: Number(row.version) }),
  account: (row) => row && ({ createdAt: new Date(row.created_at).toISOString(), createdBy: row.created_by, description: row.description, enabled: Boolean(row.enabled), expiresAt: row.expires_at ? new Date(row.expires_at).toISOString() : null, id: row.id, lastUsedAt: row.last_used_at ? new Date(row.last_used_at).toISOString() : null, name: row.name, projectIds: parseJson(row.project_ids_json, []), scopes: parseJson(row.scopes_json, []), tenantId: row.tenant_id, updatedAt: new Date(row.updated_at).toISOString(), version: Number(row.version) }),
  credential: (row) => row && ({ accountId: row.account_id, createdAt: new Date(row.created_at).toISOString(), createdBy: row.created_by, expiresAt: row.expires_at ? new Date(row.expires_at).toISOString() : null, id: row.id, lastUsedAt: row.last_used_at ? new Date(row.last_used_at).toISOString() : null, prefix: row.credential_prefix, revokedAt: row.revoked_at ? new Date(row.revoked_at).toISOString() : null, secretHash: row.secret_hash, tenantId: row.tenant_id, updatedAt: new Date(row.updated_at).toISOString(), version: Number(row.version) }),
  grant: (row) => row && ({ approvedAt: row.approved_at ? new Date(row.approved_at).toISOString() : null, approvedBy: row.approved_by, createdAt: new Date(row.created_at).toISOString(), decisionNote: row.decision_note, endedAt: row.ended_at ? new Date(row.ended_at).toISOString() : null, expiresAt: new Date(row.expires_at).toISOString(), id: row.id, reason: row.reason, requesterUserId: row.requester_user_id, status: row.status, targetUserId: row.target_user_id, tenantId: row.tenant_id, updatedAt: new Date(row.updated_at).toISOString(), version: Number(row.version) }),
};

export function createMysqlIdentityRepository({ pool }) {
  async function select(table, id, tenantId, mapper) { const [rows] = await pool.execute(`SELECT * FROM ${table} WHERE id = ? AND tenant_id = ? LIMIT 1`, [id, tenantId]); return mapper(rows[0]); }
  async function insert(table, columns, values, tenantId, mapper) { const id = randomUUID(); const now = new Date(); await pool.execute(`INSERT INTO ${table} (id, tenant_id, ${columns.join(', ')}, version, created_at, updated_at) VALUES (?, ?, ${columns.map(() => '?').join(', ')}, 1, ?, ?)`, [id, tenantId, ...values, now, now]); return select(table, id, tenantId, mapper); }
  async function update(table, id, tenantId, expectedVersion, assignments, values, mapper) { const current = await select(table, id, tenantId, (row) => row && ({ version: Number(row.version) })); if (!current) return null; const [result] = await pool.execute(`UPDATE ${table} SET ${assignments}, version = version + 1, updated_at = NOW(3) WHERE id = ? AND tenant_id = ? AND version = ?`, [...values, id, tenantId, expectedVersion]); if (Number(result.affectedRows) !== 1) conflict(current, expectedVersion); return select(table, id, tenantId, mapper); }
  async function remove(table, id, expectedVersion, tenantId) { const current = await select(table, id, tenantId, (row) => row && ({ version: Number(row.version) })); if (!current) return false; const [result] = await pool.execute(`DELETE FROM ${table} WHERE id = ? AND tenant_id = ? AND version = ?`, [id, tenantId, expectedVersion]); if (Number(result.affectedRows) !== 1) conflict(current, expectedVersion); return true; }
  return {
    async getPolicy({ tenantId }) { const [rows] = await pool.execute('SELECT * FROM tenant_identity_policies WHERE tenant_id = ? LIMIT 1', [tenantId]); return maps.policy(rows[0]); },
    async getImpersonationGrant({ grantId, tenantId }) { return select('impersonation_grants', grantId, tenantId, maps.grant); },
    async getBreakGlassPolicy({ tenantId }) { const [rows] = await pool.execute('SELECT * FROM tenant_break_glass_policies WHERE tenant_id = ? LIMIT 1', [tenantId]); return maps.breakGlassPolicy(rows[0]); },
    async upsertBreakGlassPolicy({ input, tenantId, updatedBy }) { const current = await this.getBreakGlassPolicy({ tenantId }); if ((current?.version ?? 0) !== input.expectedVersion) conflict(current ?? { version: 0 }, input.expectedVersion); const now = new Date(); if (!current) await pool.execute('INSERT INTO tenant_break_glass_policies (tenant_id, enabled, user_ids_json, max_session_minutes, updated_by, version, created_at, updated_at) VALUES (?, ?, ?, ?, ?, 1, ?, ?)', [tenantId, input.enabled, JSON.stringify(input.userIds), input.maxSessionMinutes, updatedBy, now, now]); else { const [result] = await pool.execute('UPDATE tenant_break_glass_policies SET enabled = ?, user_ids_json = ?, max_session_minutes = ?, updated_by = ?, version = version + 1, updated_at = ? WHERE tenant_id = ? AND version = ?', [input.enabled, JSON.stringify(input.userIds), input.maxSessionMinutes, updatedBy, now, tenantId, input.expectedVersion]); if (Number(result.affectedRows) !== 1) conflict(current, input.expectedVersion); } return this.getBreakGlassPolicy({ tenantId }); },
    async findVerifiedDomain({ domain }) { const [rows] = await pool.execute("SELECT * FROM tenant_verified_domains WHERE domain = ? AND status = 'verified' LIMIT 1", [domain.toLowerCase()]); return maps.domain(rows[0]); },
    async resolveUserCapabilities({ tenantId, userId }) { const [rows] = await pool.execute(`SELECT r.capabilities_json FROM identity_group_memberships m INNER JOIN identity_groups g ON g.id = m.group_id AND g.tenant_id = m.tenant_id INNER JOIN tenant_custom_roles r ON r.tenant_id = g.tenant_id AND JSON_CONTAINS(g.role_keys_json, JSON_QUOTE(r.role_key)) WHERE m.tenant_id = ? AND m.user_id = ?`, [tenantId, userId]); return [...new Set(rows.flatMap((row) => parseJson(row.capabilities_json, [])))].sort(); },
    async upsertPolicy({ input, tenantId, updatedBy }) { const current = await this.getPolicy({ tenantId }); if ((current?.version ?? 0) !== input.expectedVersion) conflict(current ?? { version: 0 }, input.expectedVersion); const now = new Date(); const values = [input.ssoMode, input.loginEnforcement, input.jitEnabled, input.defaultRoleKey, JSON.stringify(input.provider), updatedBy]; if (!current) await pool.execute('INSERT INTO tenant_identity_policies (tenant_id, sso_mode, login_enforcement, jit_enabled, default_role_key, provider_json, updated_by, version, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, 1, ?, ?)', [tenantId, ...values, now, now]); else await pool.execute('UPDATE tenant_identity_policies SET sso_mode = ?, login_enforcement = ?, jit_enabled = ?, default_role_key = ?, provider_json = ?, updated_by = ?, version = version + 1, updated_at = ? WHERE tenant_id = ? AND version = ?', [...values, now, tenantId, input.expectedVersion]); return this.getPolicy({ tenantId }); },
    createDomain: ({ input, tenantId, tokenHash }) => insert('tenant_verified_domains', ['domain', 'verification_method', 'verification_token_hash', 'status', 'verified_at'], [input.domain, input.verificationMethod, tokenHash, 'pending', null], tenantId, maps.domain),
    updateDomain: ({ domainId, input, tenantId }) => update('tenant_verified_domains', domainId, tenantId, input.expectedVersion, 'status = ?, verified_at = ?', [input.status, input.verifiedAt ? new Date(input.verifiedAt) : null], maps.domain),
    deleteDomain: ({ domainId, expectedVersion, tenantId }) => remove('tenant_verified_domains', domainId, expectedVersion, tenantId),
    createRole: ({ input, tenantId }) => insert('tenant_custom_roles', ['role_key', 'name', 'description', 'capabilities_json'], [input.key, input.name, input.description, JSON.stringify(input.capabilities)], tenantId, maps.role),
    async updateRole({ input, roleId, tenantId }) { const old = await select('tenant_custom_roles', roleId, tenantId, maps.role); if (!old) return null; const next = { ...old, ...input }; return update('tenant_custom_roles', roleId, tenantId, input.expectedVersion, 'role_key = ?, name = ?, description = ?, capabilities_json = ?', [next.key, next.name, next.description, JSON.stringify(next.capabilities)], maps.role); },
    async deleteRole({ expectedVersion, roleId, tenantId }) { const role = await select('tenant_custom_roles', roleId, tenantId, maps.role); const [groups] = await pool.execute('SELECT id FROM identity_groups WHERE tenant_id = ? AND JSON_CONTAINS(role_keys_json, JSON_QUOTE(?)) LIMIT 1', [tenantId, role?.key ?? '']); if (groups[0]) throw new HttpError(409, 'Remove this role from groups before deleting it.'); return remove('tenant_custom_roles', roleId, expectedVersion, tenantId); },
    createGroup: ({ input, tenantId }) => insert('identity_groups', ['name', 'description', 'external_id', 'role_keys_json'], [input.name, input.description, input.externalId, JSON.stringify(input.roleKeys)], tenantId, maps.group),
    async updateGroup({ groupId, input, tenantId }) { const old = await select('identity_groups', groupId, tenantId, maps.group); if (!old) return null; const next = { ...old, ...input }; return update('identity_groups', groupId, tenantId, input.expectedVersion, 'name = ?, description = ?, external_id = ?, role_keys_json = ?', [next.name, next.description, next.externalId, JSON.stringify(next.roleKeys)], maps.group); },
    async deleteGroup({ expectedVersion, groupId, tenantId }) { const current = await select('identity_groups', groupId, tenantId, maps.group); if (!current) return false; if (current.version !== expectedVersion) conflict(current, expectedVersion); const connection = await pool.getConnection(); try { await connection.beginTransaction(); const [result] = await connection.execute('DELETE FROM identity_groups WHERE id = ? AND tenant_id = ? AND version = ?', [groupId, tenantId, expectedVersion]); if (Number(result.affectedRows) !== 1) conflict(current, expectedVersion); await connection.execute('DELETE FROM identity_group_memberships WHERE tenant_id = ? AND group_id = ?', [tenantId, groupId]); await connection.commit(); return true; } catch (error) { await connection.rollback(); throw error; } finally { connection.release(); } },
    async addGroupMember({ groupId, tenantId, userId }) { await pool.execute('INSERT IGNORE INTO identity_group_memberships (id, tenant_id, group_id, user_id, created_at) VALUES (?, ?, ?, ?, NOW(3))', [randomUUID(), tenantId, groupId, userId]); const [rows] = await pool.execute('SELECT * FROM identity_group_memberships WHERE tenant_id = ? AND group_id = ? AND user_id = ? LIMIT 1', [tenantId, groupId, userId]); return maps.groupMembership(rows[0]); },
    async removeGroupMember({ groupId, tenantId, userId }) { const [result] = await pool.execute('DELETE FROM identity_group_memberships WHERE tenant_id = ? AND group_id = ? AND user_id = ?', [tenantId, groupId, userId]); return Number(result.affectedRows) > 0; },
    async createAccessReview({ input, items, tenantId, userId }) { const connection = await pool.getConnection(); try { await connection.beginTransaction(); const reviewId = randomUUID(); const now = new Date(); await connection.execute('INSERT INTO access_reviews (id, tenant_id, name, scope, reviewer_user_id, due_at, status, created_by, completed_at, version, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, NULL, 1, ?, ?)', [reviewId, tenantId, input.name, input.scope, input.reviewerUserId, new Date(input.dueAt), 'open', userId, now, now]); for (const item of items) await connection.execute('INSERT INTO access_review_items (id, tenant_id, review_id, subject_type, subject_id, access_json, decision, note, decided_by, decided_at, version, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, NULL, NULL, 1, ?, ?)', [randomUUID(), tenantId, reviewId, item.subjectType, item.subjectId, JSON.stringify(item.access), 'pending', '', now, now]); await connection.commit(); return select('access_reviews', reviewId, tenantId, maps.review); } catch (error) { await connection.rollback(); throw error; } finally { connection.release(); } },
    async createAccessReviewCampaign({ input, tenantId, userId }) { const id = randomUUID(); const now = new Date(); await pool.execute('INSERT INTO access_review_campaigns (id, tenant_id, name, scope, reviewer_user_id, interval_days, duration_days, next_run_at, enabled, created_by, last_run_at, run_count, version, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NULL, 0, 1, ?, ?)', [id, tenantId, input.name, input.scope, input.reviewerUserId, input.intervalDays, input.durationDays, new Date(input.nextRunAt), input.enabled, userId, now, now]); return select('access_review_campaigns', id, tenantId, maps.reviewCampaign); },
    async updateAccessReviewCampaign({ campaignId, input, tenantId }) { const old = await select('access_review_campaigns', campaignId, tenantId, maps.reviewCampaign); if (!old) return null; const next = { ...old, ...input }; return update('access_review_campaigns', campaignId, tenantId, input.expectedVersion, 'name = ?, scope = ?, reviewer_user_id = ?, interval_days = ?, duration_days = ?, next_run_at = ?, enabled = ?', [next.name, next.scope, next.reviewerUserId, next.intervalDays, next.durationDays, new Date(next.nextRunAt), next.enabled], maps.reviewCampaign); },
    async listDueAccessReviewCampaigns({ limit = 100, now = new Date() } = {}) { const boundedLimit = Math.max(1, Math.min(1000, Number(limit) || 100)); const [rows] = await pool.execute(`SELECT * FROM access_review_campaigns WHERE enabled = 1 AND next_run_at <= ? ORDER BY next_run_at, id LIMIT ${boundedLimit}`, [now]); return rows.map(maps.reviewCampaign); },
    async materializeAccessReviewCampaign({ campaignId, items, nextRunAt, reviewInput, scheduledFor, tenantId }) { const connection = await pool.getConnection(); try { await connection.beginTransaction(); const [campaignRows] = await connection.execute('SELECT * FROM access_review_campaigns WHERE id = ? AND tenant_id = ? FOR UPDATE', [campaignId, tenantId]); const campaign = maps.reviewCampaign(campaignRows[0]); if (!campaign || !campaign.enabled || campaign.nextRunAt !== new Date(scheduledFor).toISOString()) { await connection.rollback(); return { created: false, review: null, run: null }; } const [existingRows] = await connection.execute('SELECT * FROM access_review_campaign_runs WHERE tenant_id = ? AND campaign_id = ? AND scheduled_for = ? LIMIT 1', [tenantId, campaignId, new Date(scheduledFor)]); if (existingRows[0]) { await connection.commit(); return { created: false, review: await select('access_reviews', existingRows[0].review_id, tenantId, maps.review), run: maps.reviewCampaignRun(existingRows[0]) }; } const now = new Date(); const reviewId = randomUUID(); const reviewStatus = items.length === 0 ? 'completed' : 'open'; await connection.execute('INSERT INTO access_reviews (id, tenant_id, name, scope, reviewer_user_id, due_at, status, created_by, completed_at, version, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 1, ?, ?)', [reviewId, tenantId, reviewInput.name, reviewInput.scope, reviewInput.reviewerUserId, new Date(reviewInput.dueAt), reviewStatus, campaign.createdBy, reviewStatus === 'completed' ? now : null, now, now]); for (const item of items) await connection.execute('INSERT INTO access_review_items (id, tenant_id, review_id, subject_type, subject_id, access_json, decision, note, decided_by, decided_at, version, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, NULL, NULL, 1, ?, ?)', [randomUUID(), tenantId, reviewId, item.subjectType, item.subjectId, JSON.stringify(item.access), 'pending', '', now, now]); const runId = randomUUID(); await connection.execute('INSERT INTO access_review_campaign_runs (id, tenant_id, campaign_id, review_id, scheduled_for, version, created_at, updated_at) VALUES (?, ?, ?, ?, ?, 1, ?, ?)', [runId, tenantId, campaignId, reviewId, new Date(scheduledFor), now, now]); const [updated] = await connection.execute('UPDATE access_review_campaigns SET next_run_at = ?, last_run_at = ?, run_count = run_count + 1, version = version + 1, updated_at = ? WHERE id = ? AND tenant_id = ? AND version = ?', [new Date(nextRunAt), now, now, campaignId, tenantId, campaign.version]); if (Number(updated.affectedRows) !== 1) conflict(campaign, campaign.version); await connection.commit(); return { campaign: await select('access_review_campaigns', campaignId, tenantId, maps.reviewCampaign), created: true, review: await select('access_reviews', reviewId, tenantId, maps.review), run: await select('access_review_campaign_runs', runId, tenantId, maps.reviewCampaignRun) }; } catch (error) { await connection.rollback(); throw error; } finally { connection.release(); } },
    updateAccessReviewItem: ({ input, itemId, tenantId, userId }) => update('access_review_items', itemId, tenantId, input.expectedVersion, 'decision = ?, note = ?, decided_by = ?, decided_at = NOW(3)', [input.decision, input.note, userId], maps.reviewItem),
    async completeAccessReviewIfReady({ reviewId, tenantId }) { await pool.execute(`UPDATE access_reviews r SET r.status = 'completed', r.completed_at = NOW(3), r.version = r.version + 1, r.updated_at = NOW(3) WHERE r.id = ? AND r.tenant_id = ? AND r.status = 'open' AND NOT EXISTS (SELECT 1 FROM access_review_items i WHERE i.review_id = r.id AND i.tenant_id = r.tenant_id AND i.decision = 'pending')`, [reviewId, tenantId]); return select('access_reviews', reviewId, tenantId, maps.review); },
    createServiceAccount: ({ input, tenantId, userId }) => insert('service_accounts', ['name', 'description', 'scopes_json', 'project_ids_json', 'enabled', 'expires_at', 'last_used_at', 'created_by'], [input.name, input.description, JSON.stringify(input.scopes), JSON.stringify(input.projectIds ?? []), true, input.expiresAt ? new Date(input.expiresAt) : null, null, userId], tenantId, maps.account),
    async updateServiceAccount({ accountId, input, tenantId }) { const old = await select('service_accounts', accountId, tenantId, maps.account); if (!old) return null; const next = { ...old, ...input }; return update('service_accounts', accountId, tenantId, input.expectedVersion, 'name = ?, description = ?, scopes_json = ?, project_ids_json = ?, enabled = ?, expires_at = ?', [next.name, next.description, JSON.stringify(next.scopes), JSON.stringify(next.projectIds), next.enabled, next.expiresAt ? new Date(next.expiresAt) : null], maps.account); },
    createCredential: ({ accountId, expiresAt, prefix, secretHash, tenantId, userId }) => insert('service_account_credentials', ['account_id', 'credential_prefix', 'secret_hash', 'expires_at', 'revoked_at', 'last_used_at', 'created_by'], [accountId, prefix, secretHash, expiresAt ? new Date(expiresAt) : null, null, null, userId], tenantId, maps.credential),
    async authenticateCredential({ secretHash }) { const [rows] = await pool.execute(`SELECT c.*, a.id AS account_id_join, a.name AS account_name, a.description AS account_description, a.scopes_json AS account_scopes_json, a.project_ids_json AS account_project_ids_json, a.enabled AS account_enabled, a.expires_at AS account_expires_at, a.last_used_at AS account_last_used_at, a.created_by AS account_created_by, a.version AS account_version, a.created_at AS account_created_at, a.updated_at AS account_updated_at FROM service_account_credentials c INNER JOIN service_accounts a ON a.id = c.account_id AND a.tenant_id = c.tenant_id WHERE c.secret_hash = ? AND c.revoked_at IS NULL AND (c.expires_at IS NULL OR c.expires_at > NOW(3)) AND a.enabled = 1 AND (a.expires_at IS NULL OR a.expires_at > NOW(3)) LIMIT 1`, [secretHash]); const row = rows[0]; if (!row) return null; return { account: maps.account({ created_at: row.account_created_at, created_by: row.account_created_by, description: row.account_description, enabled: row.account_enabled, expires_at: row.account_expires_at, id: row.account_id_join, last_used_at: row.account_last_used_at, name: row.account_name, project_ids_json: row.account_project_ids_json, scopes_json: row.account_scopes_json, tenant_id: row.tenant_id, updated_at: row.account_updated_at, version: row.account_version }), credential: maps.credential(row) }; },
    async markCredentialUsed({ credentialId, tenantId }) { const connection = await pool.getConnection(); try { await connection.beginTransaction(); const [rows] = await connection.execute('SELECT account_id FROM service_account_credentials WHERE id = ? AND tenant_id = ? FOR UPDATE', [credentialId, tenantId]); if (!rows[0]) { await connection.rollback(); return false; } await connection.execute('UPDATE service_account_credentials SET last_used_at = NOW(3) WHERE id = ? AND tenant_id = ?', [credentialId, tenantId]); await connection.execute('UPDATE service_accounts SET last_used_at = NOW(3) WHERE id = ? AND tenant_id = ?', [rows[0].account_id, tenantId]); await connection.commit(); return true; } catch (error) { await connection.rollback(); throw error; } finally { connection.release(); } },
    async revokeCredentials({ accountId, tenantId }) { await pool.execute('UPDATE service_account_credentials SET revoked_at = NOW(3), version = version + 1, updated_at = NOW(3) WHERE tenant_id = ? AND account_id = ? AND revoked_at IS NULL', [tenantId, accountId]); },
    createImpersonationGrant: ({ input, requesterUserId, tenantId }) => insert('impersonation_grants', ['requester_user_id', 'target_user_id', 'reason', 'status', 'expires_at', 'approved_by', 'approved_at', 'decision_note', 'ended_at'], [requesterUserId, input.targetUserId, input.reason, 'pending', new Date(input.expiresAt), null, null, '', null], tenantId, maps.grant),
    async updateImpersonationGrant({ grantId, input, tenantId }) { const old = await select('impersonation_grants', grantId, tenantId, maps.grant); if (!old) return null; const next = { ...old, ...input }; return update('impersonation_grants', grantId, tenantId, input.expectedVersion, 'status = ?, approved_by = ?, approved_at = ?, decision_note = ?, ended_at = ?', [next.status, next.approvedBy, next.approvedAt ? new Date(next.approvedAt) : null, next.decisionNote, next.endedAt ? new Date(next.endedAt) : null], maps.grant); },
    async listSnapshot({ tenantId }) { const result = { breakGlassPolicy: await this.getBreakGlassPolicy({ tenantId }), policy: await this.getPolicy({ tenantId }) }; for (const [name, table, mapper] of [['domains', 'tenant_verified_domains', maps.domain], ['roles', 'tenant_custom_roles', maps.role], ['groups', 'identity_groups', maps.group], ['groupMemberships', 'identity_group_memberships', maps.groupMembership], ['accessReviewCampaigns', 'access_review_campaigns', maps.reviewCampaign], ['accessReviewCampaignRuns', 'access_review_campaign_runs', maps.reviewCampaignRun], ['accessReviews', 'access_reviews', maps.review], ['accessReviewItems', 'access_review_items', maps.reviewItem], ['serviceAccounts', 'service_accounts', maps.account], ['credentials', 'service_account_credentials', maps.credential], ['impersonationGrants', 'impersonation_grants', maps.grant]]) { const [rows] = await pool.execute(`SELECT * FROM ${table} WHERE tenant_id = ? ORDER BY created_at, id`, [tenantId]); result[name] = rows.map(mapper); } return result; },
    async createOidcTransaction({ codeVerifier, expiresAt, nonce, redirectPath, stateHash, tenantId }) { await pool.execute('DELETE FROM identity_oidc_transactions WHERE expires_at <= NOW(3)'); await pool.execute('INSERT INTO identity_oidc_transactions (state_hash, tenant_id, code_verifier, nonce, redirect_path, expires_at, created_at) VALUES (?, ?, ?, ?, ?, ?, NOW(3))', [stateHash, tenantId, codeVerifier, nonce, redirectPath, new Date(expiresAt)]); return { expiresAt, stateHash, tenantId }; },
    async consumeOidcTransaction({ stateHash }) { const connection = await pool.getConnection(); try { await connection.beginTransaction(); const [rows] = await connection.execute('SELECT * FROM identity_oidc_transactions WHERE state_hash = ? FOR UPDATE', [stateHash]); await connection.execute('DELETE FROM identity_oidc_transactions WHERE state_hash = ?', [stateHash]); await connection.commit(); const row = rows[0]; if (!row || new Date(row.expires_at).getTime() <= Date.now()) return null; return { codeVerifier: row.code_verifier, createdAt: new Date(row.created_at).toISOString(), expiresAt: new Date(row.expires_at).toISOString(), nonce: row.nonce, redirectPath: row.redirect_path, stateHash: row.state_hash, tenantId: row.tenant_id }; } catch (error) { await connection.rollback(); throw error; } finally { connection.release(); } },
    async createSamlTransaction({ expiresAt, redirectPath, stateHash, tenantId }) { await pool.execute('DELETE FROM identity_saml_transactions WHERE expires_at <= NOW(3)'); await pool.execute('INSERT INTO identity_saml_transactions (state_hash, tenant_id, redirect_path, request_id, cache_value, expires_at, state_consumed_at, request_consumed_at, created_at) VALUES (?, ?, ?, NULL, NULL, ?, NULL, NULL, NOW(3))', [stateHash, tenantId, redirectPath, new Date(expiresAt)]); return { expiresAt, redirectPath, stateHash, tenantId }; },
    async attachSamlRequest({ cacheValue, requestId, stateHash }) { const [result] = await pool.execute('UPDATE identity_saml_transactions SET request_id = ?, cache_value = ? WHERE state_hash = ? AND request_id IS NULL AND expires_at > NOW(3)', [requestId, cacheValue, stateHash]); if (Number(result.affectedRows) !== 1) return null; const [rows] = await pool.execute('SELECT * FROM identity_saml_transactions WHERE state_hash = ? LIMIT 1', [stateHash]); return rows[0] ? { requestId: rows[0].request_id, stateHash: rows[0].state_hash, tenantId: rows[0].tenant_id } : null; },
    async consumeSamlState({ stateHash }) { const connection = await pool.getConnection(); try { await connection.beginTransaction(); const [rows] = await connection.execute('SELECT * FROM identity_saml_transactions WHERE state_hash = ? FOR UPDATE', [stateHash]); const row = rows[0]; if (!row || row.state_consumed_at || new Date(row.expires_at).getTime() <= Date.now()) { await connection.rollback(); return null; } await connection.execute('UPDATE identity_saml_transactions SET state_consumed_at = NOW(3) WHERE state_hash = ?', [stateHash]); await connection.commit(); return { expiresAt: new Date(row.expires_at).toISOString(), redirectPath: row.redirect_path, requestId: row.request_id, stateHash: row.state_hash, tenantId: row.tenant_id }; } catch (error) { await connection.rollback(); throw error; } finally { connection.release(); } },
    async getSamlRequest({ requestId }) { const [rows] = await pool.execute('SELECT cache_value FROM identity_saml_transactions WHERE request_id = ? AND request_consumed_at IS NULL AND expires_at > NOW(3) LIMIT 1', [requestId]); return rows[0]?.cache_value ?? null; },
    async consumeSamlRequest({ requestId }) { const connection = await pool.getConnection(); try { await connection.beginTransaction(); const [rows] = await connection.execute('SELECT cache_value FROM identity_saml_transactions WHERE request_id = ? AND request_consumed_at IS NULL AND expires_at > NOW(3) FOR UPDATE', [requestId]); if (!rows[0]) { await connection.rollback(); return null; } await connection.execute('UPDATE identity_saml_transactions SET request_consumed_at = NOW(3) WHERE request_id = ? AND request_consumed_at IS NULL', [requestId]); await connection.commit(); return rows[0].cache_value; } catch (error) { await connection.rollback(); throw error; } finally { connection.release(); } },
  };
}
